import{_ as e,c as t,o as r,b2 as d}from"./chunks/framework.CUhoHPxN.js";const u=JSON.parse('{"title":"C7Cascader（C7 级联选择器）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-cascader-design.md","filePath":"superpowers/specs/2026-05-08-c7-cascader-design.md"}'),c={name:"superpowers/specs/2026-05-08-c7-cascader-design.md"};function s(a,o,n,g,l,i){return r(),t("div",null,[...o[0]||(o[0]=[d('<h1 id="c7cascader-c7-级联选择器-设计说明" tabindex="-1">C7Cascader（C7 级联选择器）设计说明 <a class="header-anchor vp-link" href="#c7cascader-c7-级联选择器-设计说明" aria-label="Permalink to &quot;C7Cascader（C7 级联选择器）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「设计批准」）<br><strong>依据</strong>：<code>原始需求/前端/C7级联选择器.md</code> + Q&amp;A 结论（<strong>1A、2B、3A、4A、5A</strong>）<br><strong>方案选型</strong>：<strong>方案一</strong> — 单文件封装，结构与 <code>C7TreeSelect</code> / <code>C7Select</code> 对齐（不额外抽 composable，待树系重复逻辑明显增多时再考虑抽取）。</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：后端常返回树形数据（地区、部门、分类等），业务需要级联选择；同时要统一<strong>整树一次加载</strong>与<strong>按层懒加载</strong>两种模式，以及<strong>字段映射</strong>与<strong>对外值格式</strong>（与现有 C7 下拉/树选一致）。</li><li><strong>目标</strong>：在 <strong>Element Plus <code>ElCascader</code></strong> 之上封装：<strong>静态 <code>dataList</code> / 整树 <code>fetchData</code> / 懒加载 <code>fetchData</code></strong>、<code>resultKey</code> + <code>dataFormatter</code>、<strong><code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code></strong> 映射、<strong><code>multiple</code> + <code>separator</code></strong> 与 <strong><code>valueType</code></strong>、<strong><code>load-error</code> / <code>loading-change</code></strong>；其余行为与 EP 透传属性保持一致（尤其 <strong><code>emitPath</code> / <code>checkStrictly</code></strong> 下的值语义）。</li><li><strong>非目标</strong>：不替代或 fork EP 级联面板实现；不在本期承诺「任意 <code>emitPath</code> 组合下均可用英文逗号 <code>separator</code> 无损表达」（见第 7.3 节限制）。</li></ul><hr><h2 id="_2-组件边界与落点" tabindex="-1">2. 组件边界与落点 <a class="header-anchor vp-link" href="#_2-组件边界与落点" aria-label="Permalink to &quot;2. 组件边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>组件名</strong></td><td><strong><code>C7Cascader</code></strong></td></tr><tr><td><strong>目录</strong></td><td><code>quick-ui/src/packages/C7Cascader/index.vue</code>（单文件；与当前 <code>C7TreeSelect</code> 体量同量级）</td></tr><tr><td><strong>注册</strong></td><td>在 <code>quick-ui/src/packages/index.js</code> 中 <strong>export</strong> 与 <strong><code>installPackages</code></strong> 注册（与现有 C7 包一致）</td></tr><tr><td><strong>与 EP 关系</strong></td><td><code>inheritAttrs: false</code>；<strong>保留字</strong>内的 props 由本组件消费，<strong>其余 attrs 透传</strong>至 <code>ElCascader</code>（含 <code>emitPath</code>、<code>checkStrictly</code>、<code>props</code>、<code>show-all-levels</code> 等）。</td></tr></tbody></table></div><hr><h2 id="_3-技术选型" tabindex="-1">3. 技术选型 <a class="header-anchor vp-link" href="#_3-技术选型" aria-label="Permalink to &quot;3. 技术选型&quot;">​</a></h2><ul><li><strong>基底</strong>：<code>ElCascader</code>（版本与工程内 Element Plus 保持一致）。</li><li><strong>懒加载</strong>：使用 EP 支持的 <strong><code>lazy</code> + <code>lazyLoad</code></strong>；在 <code>lazyLoad</code> 回调内调用业务 <strong><code>fetchData</code></strong>，将返回的<strong>当前层子节点扁平列表</strong>规范为节点列表后 <strong><code>resolve</code></strong>（或 EP 要求的完成方式）。</li><li><strong>命名与 C7 统一</strong>：多选逗号串使用布尔 <strong><code>separator</code></strong>（<strong>不使用</strong>原始需求稿中的 <code>resultType</code> 枚举，避免与 <code>C7Select</code> / <code>C7TreeSelect</code> 分裂）。</li></ul><hr><h2 id="_4-数据来源与加载时机" tabindex="-1">4. 数据来源与加载时机 <a class="header-anchor vp-link" href="#_4-数据来源与加载时机" aria-label="Permalink to &quot;4. 数据来源与加载时机&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>模式</th><th>条件</th><th>行为</th></tr></thead><tbody><tr><td><strong>静态</strong></td><td><code>dataList</code> 或 <code>options</code> 已绑定</td><td><strong><code>dataList !== undefined</code> 时仅用 <code>dataList</code></strong>（与 <code>C7TreeSelect</code> 一致）；不发起 <code>fetchData</code>。数据经 <code>mapTree</code> 后作为 <code>options</code>。</td></tr><tr><td><strong>整树异步</strong></td><td>无静态绑定、<strong>非懒加载</strong>（<code>lazy</code> 不为真或未启用懒加载语义）、且提供 <code>fetchData</code></td><td>当 <strong><code>autoLoad === true</code></strong> 时，在 <strong><code>onMounted</code></strong> 调用 <strong><code>fetchData({ ...fetchParams })</code></strong>（<strong>不含 <code>parentId</code></strong>）。响应解析规则与 <code>C7TreeSelect</code> 一致（见第 5 节）。</td></tr><tr><td><strong>懒加载</strong></td><td><code>lazy === true</code> 且提供 <code>fetchData</code></td><td>根层：首次由 EP 触发懒加载时调用 <strong><code>fetchData({ parentId: rootParentId, ...fetchParams })</code></strong>。子层：<strong><code>parentId</code> 取当前父节点在映射后的 <code>value</code></strong>（即业务 <code>valueKey</code> 字段映射结果，保证与接口约定一致）。</td></tr></tbody></table></div><ul><li><strong><code>rootParentId</code></strong>：类型与默认值在实现阶段与常见后端约定对齐（如 <code>null</code> / <code>0</code> / <code>&#39;&#39;</code>）；<strong>文档与 JSDoc 必须写清</strong>「根节点请求使用的 <code>parentId</code>」。</li><li><strong><code>autoLoad</code></strong>：语义对齐 <code>C7TreeSelect</code>；若 <code>autoLoad=true</code> 但未提供 <code>fetchData</code>，<strong>DEV</strong> 下 <strong><code>console.warn</code></strong> 并跳过（与树选一致）。</li></ul><hr><h2 id="_5-响应解析与字段映射-含-resultkey-语义" tabindex="-1">5. 响应解析与字段映射（含 <code>resultKey</code> 语义） <a class="header-anchor vp-link" href="#_5-响应解析与字段映射-含-resultkey-语义" aria-label="Permalink to &quot;5. 响应解析与字段映射（含 `resultKey` 语义）&quot;">​</a></h2><ul><li><strong><code>resultKey</code></strong>：与 <code>C7Select</code> / <code>C7TreeSelect</code> 相同 — 从 <strong><code>fetchData</code> 返回的 <code>res.data</code></strong> 上按 <strong>lodash <code>get</code> 点路径</strong>取列表（如 <code>rows</code>、<code>data.list</code>）；<strong>不</strong>表示「子节点字段名」。</li><li><strong><code>dataFormatter</code></strong>：在 <code>resultKey</code> 解析之后、<strong>数组校验</strong>之前对列表做最终整形；返回须为数组（否则按空数组处理）。</li><li><strong><code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code></strong>：输入侧业务树字段名；内部 <strong><code>mapTree</code></strong> 规范为 EP 所需 <strong><code>{ label, value, children }</code></strong>。静态与整树异步路径下，若子层已有 <code>childrenKey</code> 数组则递归映射；懒加载单层返回为<strong>扁平子列表</strong>，由组件挂到父节点 <strong><code>children</code></strong>。</li><li><strong>禁用</strong>：节点对象上 <strong><code>disabled === true</code></strong> 时映射为 EP 节点 <strong><code>disabled: true</code></strong>（与 <code>C7TreeSelect</code> 一致）。</li></ul><hr><h2 id="_6-懒加载接口约定-对应-q-a-2b、3a" tabindex="-1">6. 懒加载接口约定（对应 Q&amp;A <strong>2B、3A</strong>） <a class="header-anchor vp-link" href="#_6-懒加载接口约定-对应-q-a-2b、3a" aria-label="Permalink to &quot;6. 懒加载接口约定（对应 Q&amp;A **2B、3A**）&quot;">​</a></h2><ul><li><strong>入参</strong>：<strong><code>{ parentId, ...fetchParams }</code></strong>（浅拷贝合并 <code>fetchParams</code>）；根层 <strong><code>parentId === rootParentId</code></strong>。</li><li><strong>出参</strong>：当前父节点下的 <strong>子节点扁平数组</strong>；元素形状与整树节点一致（含业务字段），由 <strong><code>mapTree</code> 的单层映射</strong> 转为 EP 节点（子层若无下级，可不返回 <code>childrenKey</code> 或返回空数组，<strong>叶子</strong>语义与 EP 一致）。</li><li><strong>错误</strong>：单次 <code>fetchData</code> reject → <strong><code>load-error</code></strong>（载荷为 <strong><code>err</code></strong> 原样，与 <code>C7TreeSelect</code> 一致）；<strong>不替业务决定</strong>是否 <code>ElMessage</code>。</li><li><strong>并发</strong>：使用 <strong><code>fetchGeneration</code></strong> 或等价机制，忽略过期回调写入；<strong><code>loading-change</code></strong> 与 <strong><code>inFlightCount</code></strong> 语义对齐树选（内部请求进行中为 <code>true</code>，可与 attrs 传入的 <code>loading</code> <strong>OR</strong> 合并若 EP 支持该 prop）。</li></ul><hr><h2 id="_7-对外值、valuetype-与-separator-对应-q-a-1a、4a" tabindex="-1">7. 对外值、<code>valueType</code> 与 <code>separator</code>（对应 Q&amp;A <strong>1A、4A</strong>） <a class="header-anchor vp-link" href="#_7-对外值、valuetype-与-separator-对应-q-a-1a、4a" aria-label="Permalink to &quot;7. 对外值、`valueType` 与 `separator`（对应 Q&amp;A **1A、4A**）&quot;">​</a></h2><h3 id="_7-1-与-element-plus-一致的部分" tabindex="-1">7.1 与 Element Plus 一致的部分 <a class="header-anchor vp-link" href="#_7-1-与-element-plus-一致的部分" aria-label="Permalink to &quot;7.1 与 Element Plus 一致的部分&quot;">​</a></h3><ul><li><strong><code>emitPath</code> / <code>checkStrictly</code> / <code>multiple</code></strong>：不修改 EP 文档定义；<strong><code>v-model</code> 在「非 C7 适配层」上</strong>与 EP 一致（路径数组 vs 叶子值等）。</li></ul><h3 id="_7-2-valuetype-auto-string-number" tabindex="-1">7.2 <code>valueType</code>（<code>auto</code> | <code>string</code> | <code>number</code>） <a class="header-anchor vp-link" href="#_7-2-valuetype-auto-string-number" aria-label="Permalink to &quot;7.2 `valueType`（`auto` | `string` | `number`）&quot;">​</a></h3><ul><li>语义对齐 <strong><code>C7TreeSelect</code></strong>：<strong><code>auto</code></strong> 时以<strong>规范后选项数据中用于推断的样本节点</strong>的 <code>value</code> 类型为准（实现上可取<strong>首帧根层第一条</strong>或数据到达后的稳定样本，与树选文档描述一致）；<strong>标量</strong>进出做 <code>String</code> / <code>Number</code> 转换。</li><li><strong>路径形态</strong>（<code>emitPath === true</code>）：对路径中<strong>各层标量</strong>做 <code>valueType</code> 约定转换；嵌套数组结构本身不变。</li></ul><h3 id="_7-3-separator-的适用边界-重要" tabindex="-1">7.3 <code>separator</code> 的适用边界（重要） <a class="header-anchor vp-link" href="#_7-3-separator-的适用边界-重要" aria-label="Permalink to &quot;7.3 `separator` 的适用边界（重要）&quot;">​</a></h3><ul><li>与 <strong><code>C7Select</code> / <code>C7TreeSelect</code></strong> 相同：<strong><code>separator === true</code></strong> 时，多选对外为 <strong>英文逗号拼接的字符串</strong>，空选为 <strong><code>&#39;&#39;</code></strong>；对内为 EP 所需数组结构。</li><li><strong>限制</strong>：当 <strong><code>emitPath === true</code></strong> 或 EP 内部值为<strong>非一维标量列表</strong>（例如<strong>路径为嵌套数组</strong>）时，<strong>逗号拼接不适用或无唯一逆解析</strong>。本期约定： <ul><li><strong>实现</strong>：在此类组合下 <strong><code>separator</code> 视为无效</strong>，对外仍输出 <strong>与 EP 一致的数组结构</strong>；<strong>DEV</strong> 下 <strong><code>console.warn</code></strong> 说明原因。</li><li><strong>文档</strong>：明确写出「<strong>仅当 <code>emitPath === false</code> 且多选值为叶子标量数组时，推荐使用 <code>separator</code></strong>」，与「value 含英文逗号勿用 <code>separator</code>」并列说明。</li></ul></li></ul><hr><h2 id="_8-事件与加载展示" tabindex="-1">8. 事件与加载展示 <a class="header-anchor vp-link" href="#_8-事件与加载展示" aria-label="Permalink to &quot;8. 事件与加载展示&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>事件</th><th>说明</th></tr></thead><tbody><tr><td><strong><code>update:modelValue</code></strong></td><td>对外形态经 <strong>§7</strong> 转换后的值。</td></tr><tr><td><strong><code>change</code></strong></td><td>载荷与 <strong><code>update:modelValue</code></strong> 一致。</td></tr><tr><td><strong><code>visible-change</code></strong></td><td>透传 EP 下拉/面板可见性。</td></tr><tr><td><strong><code>loading-change</code></strong></td><td><strong><code>true</code></strong> 表示本组件发起的 <strong><code>fetchData</code> 仍有未完成请求</strong>（与 <code>C7TreeSelect</code> 一致）。</td></tr><tr><td><strong><code>load-error</code></strong></td><td><strong><code>fetchData</code> reject</strong> 时触发，参数为 <strong><code>err</code></strong>。</td></tr></tbody></table></div><hr><h2 id="_9-与-c7treeselect-的差异说明-文档与示例职责" tabindex="-1">9. 与 <code>C7TreeSelect</code> 的差异说明（文档与示例职责） <a class="header-anchor vp-link" href="#_9-与-c7treeselect-的差异说明-文档与示例职责" aria-label="Permalink to &quot;9. 与 `C7TreeSelect` 的差异说明（文档与示例职责）&quot;">​</a></h2><ul><li><strong>交互形态</strong>：级联为<strong>级联面板</strong>，树选为<strong>树形下拉</strong>；二者均可能对接树形接口，但 UX 不同。</li><li><strong>选型建议（写入 VitePress）</strong>：<strong>级联多步、层级深、每步选项少</strong>优先 <strong>C7Cascader</strong>；<strong>需在一棵树内搜索/勾选/展示复杂节点</strong>优先 <strong>C7TreeSelect</strong>（表述可为建议非强制）。</li></ul><hr><h2 id="_10-验收标准-与原始需求对齐" tabindex="-1">10. 验收标准（与原始需求对齐） <a class="header-anchor vp-link" href="#_10-验收标准-与原始需求对齐" aria-label="Permalink to &quot;10. 验收标准（与原始需求对齐）&quot;">​</a></h2><ol><li><strong>非懒加载</strong>：无静态数据、<code>autoLoad=true</code>、<code>fetchData</code> 可用时，挂载后能自动出现 <strong>options</strong>（失败则 <strong><code>load-error</code></strong>，options 可为空）。</li><li><strong>懒加载</strong>：展开节点会按 <strong><code>{ parentId, ...fetchParams }</code></strong> 调用 <strong><code>fetchData</code></strong>，子层出现预期选项。</li><li><strong>多选</strong>：在 <strong>§7.3 允许的组合</strong>下，<strong><code>separator</code></strong> 对外为逗号分隔字符串；否则为数组且不静默损坏数据。</li><li><strong>字段映射</strong>：<code>labelKey</code> / <code>valueKey</code> / <code>childrenKey</code> 在静态、整树、懒加载下均生效。</li></ol><hr><h2 id="_11-实现阶段建议-非本期设计强制细节" tabindex="-1">11. 实现阶段建议（非本期设计强制细节） <a class="header-anchor vp-link" href="#_11-实现阶段建议-非本期设计强制细节" aria-label="Permalink to &quot;11. 实现阶段建议（非本期设计强制细节）&quot;">​</a></h2><ul><li><strong>文档</strong>：<code>docs/docs/frontend/components/通用组件/c7-cascader.md</code>（或团队约定路径）+ 可选 <strong><code>views/dev</code></strong> 演示页（与 <code>C7SelectE2E</code> 类同，按需）。</li><li><strong>测试</strong>：以演示页或单测覆盖 <strong>整树加载</strong>、<strong>懒加载一层</strong>、<strong><code>separator</code> + <code>emitPath=false</code></strong>、<strong><code>load-error</code></strong> 为主。</li></ul><hr><h2 id="_12-修订记录" tabindex="-1">12. 修订记录 <a class="header-anchor vp-link" href="#_12-修订记录" aria-label="Permalink to &quot;12. 修订记录&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>日期</th><th>说明</th></tr></thead><tbody><tr><td>2026-05-08</td><td>初版定稿：brainstorming Q&amp;A 1A–5A + 方案一</td></tr></tbody></table></div>',44)])])}const p=e(c,[["render",s]]);export{u as __pageData,p as default};
